 ******************************************************************************************************/
func searchRange(nums []int, target int) []int {
	ans := []int{-1, -1}
	if len(nums) == 0 {
		return ans
	}
	left := binSearchLeft(nums, target)
	if left == -1 {
		return ans
	}
	right := binSearchRight(nums, target)
	ans[0] = left
	ans[1] = right
	return ans
}

func binSearchLeft(nums []int, target int) int {
	var (
		left  = 0
		right = len(nums) - 1
		mid   = 0
	)
	for left <= right {
		mid = left + (right-left)/2
		if nums[mid] == target {
			right = mid - 1
		} else if nums[mid] < target {
			left = mid + 1
		} else if nums[mid] > target {
			right = mid - 1
		}
	}
	if left >= len(nums) || nums[left] != target {
		return -1
	}
	return left
}
func binSearchRight(nums []int, target int) int {
	var (
		left  = 0
		right = len(nums) - 1
		mid   = 0
	)
	for left <= right {
		mid = left + (right-left)/2
		if nums[mid] == target {
			left = mid + 1
		} else if nums[mid] < target {
			left = mid + 1
		} else if nums[mid] > target {
			right = mid - 1
		}
	}
	if right < 0 || nums[right] != target {
		return -1
	}
	return right
}

