            if (target == nums[mid] &&
                (mid == nums.size() - 1 || target != nums[mid + 1])) {
                ans.push_back(mid);
                break;
            } else if (target < nums[mid]) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }
        return ans;
